    1 //! ssc-6 (D-2026-09-28-1, D-2026-09-28-3): end-of-run retry passes over
    2 //! the files that failed.
    3 //!
    4 //! Owner's rule: "collect all errors, then … retry at the end of the
    5 //! transfer that will rescan and retry." After a route's main pass, if
    6 //! it recorded per-file failures and `--retries` is non-zero, the
    7 //! orchestrator waits `--retry-wait` seconds and runs one further
    8 //! session limited to exactly those paths (`FileFilter.files_from`),
    9 //! re-scanned fresh through the same machinery, pass after pass, until
   10 //! a pass ends with no failures or `--retries` passes have run. Files
   11 //! that land on a retry count once as transferred and leave the
   12 //! report; files that fail again are reported once, their reason
   13 //! marked `(retried)`. The final state is what the exit status, the
   14 //! JSON fields and the move source-delete gate read.
   15 //!
   16 //! Retry passes never mirror-delete: deletions are planned by the main
   17 //! pass from its complete source set (with the failed paths shielding
   18 //! their destination subtrees, A19); a retry pass only transfers.
   19 //!
   20 //! No prompt in any mode — unattended runs must not hang — and no other
   21 //! switch: `--retries 0` is how a caller opts out.
   22 
   23 use std::collections::HashSet;
   24 use std::future::Future;
   25 use std::path::PathBuf;
   26 use std::time::Duration;
   27 
   28 use blit_core::generated::TransferSummary;
   29 use blit_core::remote::transfer::FileFailure;
   30 use blit_core::transfer_session::local::LocalMirrorSummary;
   31 use blit_core::transfers::remote::DelegatedPullOutcome;
   32 use eyre::Result;
   33 
   34 use crate::cli::TransferArgs;
   35 
   36 /// The failure report of one pass, in the one shape every route
   37 /// produces: the exact count, the named (capped) report, and the exact
   38 /// path set the next pass retries.
   39 #[derive(Clone, Debug, Default)]
   40 pub(crate) struct PassFailures {
   41     pub files_failed: u64,
   42     pub failures: Vec<FileFailure>,
   43     pub failed_paths: Vec<String>,
   44     pub failed_paths_truncated: bool,
   45 }
   46 
   47 impl PassFailures {
   48     pub(crate) fn from_summary(summary: &TransferSummary) -> Self {
   49         Self {
   50             files_failed: summary.files_failed,
   51             failures: super::failures::failures_from_wire(&summary.failures),
   52             failed_paths: summary.failed_paths.clone(),
   53             failed_paths_truncated: summary.failed_paths_truncated,
   54         }
   55     }
   56 
   57     pub(crate) fn from_local(summary: &LocalMirrorSummary) -> Self {
   58         Self {
   59             files_failed: summary.files_failed,
   60             failures: summary.failures.clone(),
   61             failed_paths: summary.failed_paths.clone(),
   62             failed_paths_truncated: summary.failed_paths_truncated,
   63         }
   64     }
   65 
   66     pub(crate) fn from_delegated(outcome: &DelegatedPullOutcome) -> Self {
   67         let (paths, truncated) = outcome.failed_paths();
   68         Self {
   69             files_failed: outcome.files_failed(),
   70             failures: outcome.contained_failures(),
   71             failed_paths: paths.to_vec(),
   72             failed_paths_truncated: truncated,
   73         }
   74     }
   75 
   76     /// The set the next pass is limited to. The exact set when the
   77     /// sender could carry it; otherwise the named report's paths, with
   78     /// `truncated` telling the caller to say so.
   79     fn retry_set(&self) -> (HashSet<PathBuf>, bool) {
   80         if !self.failed_paths_truncated && !self.failed_paths.is_empty() {
   81             return (self.failed_paths.iter().map(PathBuf::from).collect(), false);
   82         }
   83         let truncated =
   84             self.failed_paths_truncated || (self.files_failed as usize) > self.failures.len();
   85         (
   86             self.failures
   87                 .iter()
   88                 .map(|f| PathBuf::from(&f.relative_path))
   89                 .collect(),
   90             truncated,
   91         )
   92     }
   93 
   94     /// Mark every remaining failure as one that survived a retry.
   95     fn mark_retried(&mut self) {
   96         for failure in &mut self.failures {
   97             if !failure.reason.ends_with(RETRIED_SUFFIX) {
   98                 failure.reason.push_str(RETRIED_SUFFIX);
   99             }
  100         }
  101     }
  102 
  103     /// Write the final state back onto a wire-shaped summary.
  104     pub(crate) fn apply_to_summary(&self, summary: &mut TransferSummary) {
  105         summary.files_failed = self.files_failed;
  106         summary.failures = self.failures.iter().map(FileFailure::to_wire).collect();
  107         summary.failed_paths = self.failed_paths.clone();
  108         summary.failed_paths_truncated = self.failed_paths_truncated;
  109     }
  110 
  111     /// Write the final state back onto a local summary.
  112     pub(crate) fn apply_to_local(&self, summary: &mut LocalMirrorSummary) {
  113         summary.files_failed = self.files_failed;
  114         summary.failures = self.failures.clone();
  115         summary.failed_paths = self.failed_paths.clone();
  116         summary.failed_paths_truncated = self.failed_paths_truncated;
  117     }
  118 }
