  123 /// What one retry pass returns to the loop.
  124 pub(crate) struct PassResult {
  125     pub files_transferred: u64,
  126     pub bytes_transferred: u64,
  127     pub failures: PassFailures,
  128 }
  129 
  130 /// What the loop hands back for the route to fold into its final
  131 /// summary: the files and bytes the retries added, the final failure
  132 /// state, and how many passes ran.
  133 pub(crate) struct RetryOutcome {
  134     pub added_files: u64,
  135     pub added_bytes: u64,
  136     pub final_failures: PassFailures,
  137     pub passes_run: u32,
  138 }
  139 
  140 impl RetryOutcome {
  141     /// Fold the retries into a wire-shaped summary: files and bytes the
  142     /// retries landed are added once, and the failure report becomes the
  143     /// final state.
  144     pub(crate) fn fold_into_summary(&self, summary: &mut TransferSummary) {
  145         if self.passes_run == 0 {
  146             return;
  147         }
  148         summary.files_transferred = summary.files_transferred.saturating_add(self.added_files);
  149         summary.bytes_transferred = summary.bytes_transferred.saturating_add(self.added_bytes);
  150         self.final_failures.apply_to_summary(summary);
  151     }
  152 
  153     /// The delegated re-encode's shape of the same fold.
  154     pub(crate) fn fold_into_delegated(
  155         &self,
  156         summary: &mut blit_core::generated::DelegatedPullSummary,
  157     ) {
  158         if self.passes_run == 0 {
  159             return;
  160         }
  161         summary.files_transferred = summary.files_transferred.saturating_add(self.added_files);
  162         summary.bytes_transferred = summary.bytes_transferred.saturating_add(self.added_bytes);
  163         summary.files_failed = self.final_failures.files_failed;
  164         summary.failures = self
  165             .final_failures
  166             .failures
  167             .iter()
  168             .map(FileFailure::to_wire)
  169             .collect();
  170         summary.failed_paths = self.final_failures.failed_paths.clone();
  171         summary.failed_paths_truncated = self.final_failures.failed_paths_truncated;
  172     }
  173 }
