   54 /// Render an endpoint for human-facing log lines, collapsing any runs of
   55 /// `/` into a single `/` in the local-path portion. Filesystems already
   56 /// ignore `//+`, but users stare at it — our own banner printed
   57 /// `src//foo` when a script appended `/` to an already-trailing-slash
   58 /// `$SRC`. This is display-only; the actual path handling is unchanged
   59 /// so rsync trailing-slash semantics still apply.
   60 fn display_endpoint(e: &Endpoint) -> String {
   61     match e {
   62         Endpoint::Local(p) => collapse_slashes(&p.display().to_string()),
   63         Endpoint::Remote(r) => format_remote_endpoint(r),
   64     }
   65 }
   66 
   67 fn collapse_slashes(s: &str) -> String {
   68     let mut out = String::with_capacity(s.len());
   69     let mut prev_slash = false;
   70     for c in s.chars() {
   71         let is_slash = c == '/';
   72         if !(is_slash && prev_slash) {
   73             out.push(c);
   74         }
   75         prev_slash = is_slash;
   76     }
   77     out
   78 }
