   92 /// Prompt for confirmation of a destructive operation. Returns true if the user confirms.
   93 /// Always returns true if `skip_prompt` is true.
   94 fn confirm_destructive_operation(message: &str, skip_prompt: bool) -> Result<bool> {
   95     if skip_prompt {
   96         return Ok(true);
   97     }
   98 
   99     print!("{} [y/N]: ", message);
  100     io::stdout().flush()?;
  101     let mut input = String::new();
  102     io::stdin().read_line(&mut input)?;
  103     let decision = input.trim().to_ascii_lowercase();
  104     Ok(decision == "y" || decision == "yes")
  105 }
