  114 fn prepare_transfer_route(
  115     args: &TransferArgs,
  116     mode: TransferKind,
  117     lifecycle_trace: &TransferLifecycleTrace,
  118 ) -> Result<PreparedTransferRoute> {
  119     lifecycle_trace.record("transfer_route_select_begin", None);
  120     let prepared = (|| {
  121         let src_endpoint = parse_transfer_endpoint(&args.source)?;
  122         let raw_dst = parse_transfer_endpoint(&args.destination)?;
  123         let pre_resolve_display = display_endpoint(&raw_dst);
  124         let dst_endpoint =
  125             resolve_destination(&args.source, &args.destination, &src_endpoint, raw_dst);
  126         let src_display = display_endpoint(&src_endpoint);
  127         let dst_display = display_endpoint(&dst_endpoint);
  128         let route = select_transfer_route(src_endpoint, dst_endpoint, mode);
  129         Ok(PreparedTransferRoute {
  130             route,
  131             pre_resolve_display,
  132             src_display,
  133             dst_display,
  134         })
  135     })();
  136 
  137     match &prepared {
  138         Ok(prepared) => {
  139             match &prepared.route {
  140                 TransferRoute::LocalToRemote { .. } => {
  141                     lifecycle_trace.attach_initiator_role(SessionPhaseRole::Source);
  142                 }
  143                 TransferRoute::RemoteToLocal { .. }
  144                 | TransferRoute::RemoteToRemoteDelegated { .. } => {
  145                     lifecycle_trace.attach_initiator_role(SessionPhaseRole::Destination);
  146                 }
  147                 TransferRoute::LocalToLocal { .. } => {}
  148             }
  149             lifecycle_trace.record(
  150                 "transfer_route_select_end",
  151                 Some(TransferLifecycleOutcome::Success),
  152             );
  153         }
  154         Err(err) => lifecycle_trace.record(
  155             "transfer_route_select_end",
  156             Some(blit_core::remote::transfer::outcome_for_report(err)),
  157         ),
  158     }
  159     prepared
  160 }
