   52 fn command(verb: &str, extra: &[&str], src: &Path, dst: &Path, counters: &Path) -> Command {
   53     let mut cmd = Command::new(cli_bin());
   54     cmd.arg("--diagnostics-counter-file").arg(counters);
   55     cmd.arg(verb).arg("--yes");
   56     for arg in extra {
   57         cmd.arg(arg);
   58     }
   59     cmd.arg(format!("{}/", src.display()))
   60         .arg(format!("{}/", dst.display()));
   61     cmd
   62 }
   63 
   64 fn run(verb: &str, extra: &[&str], src: &Path, dst: &Path, counters: &Path) -> Output {
   65     run_with_timeout(
   66         command(verb, extra, src, dst, counters),
   67         Duration::from_secs(90),
   68     )
   69 }
   70 
   71 fn spawn(verb: &str, extra: &[&str], src: &Path, dst: &Path, counters: &Path) -> Child {
   72     command(verb, extra, src, dst, counters)
   73         .stdout(Stdio::piped())
   74         .stderr(Stdio::piped())
   75         .spawn()
   76         .expect("spawn blit")
   77 }
   78 
   79 fn counter_lines(counters: &Path, event: &str) -> Vec<u64> {
   80     fs::read_to_string(counters)
   81         .unwrap_or_default()
   82         .lines()
   83         .filter_map(|line| {
   84             let (name, value) = line.split_once(' ')?;
   85             (name == event).then(|| value.parse::<u64>().ok()).flatten()
   86         })
   87         .collect()
   88 }
