   90 /// Block until the counter file carries `event`, or fail loudly.
   91 fn wait_for_counter(counters: &Path, event: &str, timeout: Duration) {
   92     let start = Instant::now();
   93     while start.elapsed() < timeout {
   94         if !counter_lines(counters, event).is_empty() {
   95             return;
   96         }
   97         std::thread::sleep(Duration::from_millis(25));
   98     }
   99     panic!("no `{event}` counter within {timeout:?}");
  100 }
