  120         args.json,
  121         defer_output, // R53-F1: suppress final progress line on move
  122     );
  123 
  124     let dst_label = format_remote_endpoint(&dst);
  125     let execution = DelegatedPullExecution {
  126         src,
  127         dst,
  128         options,
  129         trace_data_plane: args.trace_data_plane,
  130         dst_label,
  131         // `--detach` is only honored on remote→remote
  132         // delegated pulls (this code path). `run_transfer`
  133         // rejects the flag on push / pull / pull_sync routes
  134         // upstream, so we don't need to gate it here — but
  135         // the daemon also refuses to honor it on those
  136         // RPCs, so a misbehaving caller can't escape the
  137         // CLI in-byte-path guarantee.
  138         detach: args.detach,
  139         lifecycle_trace: lifecycle_trace.clone(),
  140         perf_history,
  141     };
  142 
  143     // --detach exit-after-Started path. Opens the stream
  144     // just long enough to learn the daemon-assigned
  145     // transfer_id (which arrives on the Started event after
  146     // m-jobs-3) and then drops the receiver. The daemon's
  147     // tx.closed race is disarmed by `detach=true`, so the
  148     // transfer continues. We synthesize a zero-summary
  149     // outcome so the existing callers (`run_remote_to_remote_direct`
  150     // which discards it; `_deferred` which is rejected up
  151     // front for detach via run_move's gate) see a stable
  152     // shape.
  153     if args.detach {
  154         // Tear down the progress monitor before printing —
  155         // same posture as the non-detach success path, so
  156         // any in-flight `[progress]` line doesn't get
  157         // interleaved with the detach output.
  158         drop(progress_handle);
  159         if let Some(task) = progress_task {
  160             let _ = task.await;
  161         }
  162 
  163         let dst_for_state = execution.dst.clone();
  164         // The cancel/status hint references the destination
  165         // host as the argument to `blit jobs`. Derive it
  166         // from the parsed `RemoteEndpoint` rather than the
  167         // raw CLI input — string-splitting `args.destination`
  168         // breaks `host:port:/module/path` (port dropped) and
  169         // bracketed IPv6 (`[::1]:9031:/m/p` truncates to
  170         // just `[`). `host_port_display` handles both via
  171         // the same helper `RemoteEndpoint::display` already
  172         // uses.
  173         let dst_host_hint = dst_for_state.host_port_display();
  174 
  175         let (started, _dst) = run_delegated_pull_until_started(execution).await?;
  176         let transfer_id = started.transfer_id.clone();
  177         let summary = DelegatedPullSummary {
  178             files_transferred: 0,
  179             bytes_transferred: 0,
  180             bytes_zero_copy: 0,
  181             tcp_fallback_used: false,
  182             entries_deleted: 0,
  183             source_peer_observed: started.source_data_plane_endpoint.clone(),
  184             // A detached caller exits before the destination computes
  185             // any summary, so it observes no counts at all — including
  186             // the per-file failure report (cr-pfc4-1). The daemon owns
  187             // the transfer to completion; `blit jobs` is where its
  188             // outcome is read.
  189             files_failed: 0,
  190             failures: Vec::new(),
  191             failed_paths: Vec::new(),
  192             failed_paths_truncated: false,
  193         };
  194         let state = DeferredDelegatedState {
  195             summary,
  196             src: dst_for_state.clone(), // source endpoint not surfaced on Started
  197             dst: dst_for_state,
  198         };
  199         super::render_result(lifecycle_trace, || {
  200             if args.json {
  201                 print_detach_json(&transfer_id);
  202             } else {
  203                 print_detach_human(&transfer_id, &dst_host_hint);
  204             }
  205             Ok(())
  206         })?;
  207         return Ok(state);
  208     }
  209 
  210     // CLI-side presentation hook for the destination's `Started`
  211     // event: display-only, so the closure must stay free of any
  212     // effect the transfer depends on.
  213     let verbose_human = args.verbose && !args.json;
  214     let outcome = run_delegated_pull(execution, progress_handle.as_ref(), |started| {
  215         if verbose_human {
  216             eprintln!(
  217                 "blit: delegation: destination pulling from {} ({} stream(s))",
  218                 started.source_data_plane_endpoint, started.stream_count
  219             );
  220         }
  221     })
  222     .await;
  223 
  224     drop(progress_handle);
  225     if let Some(task) = progress_task {
  226         let _ = task.await;
  227     }
  228 
  229     let state = outcome?;
  230     if !defer_output {
  231         super::render_result(lifecycle_trace, || {
  232             print_deferred_delegated_result(args, &state);
  233             Ok(())
  234         })?;
  235     }
  236     Ok(state)
  237 }
