  239 fn print_detach_human(transfer_id: &str, dst_host_hint: &str) {
  240     eprintln!(
  241         "Detached transfer {transfer_id}; daemon owns it to completion or cancel.\n  cancel: blit jobs cancel {dst_host_hint} {transfer_id}\n  status: blit jobs list {dst_host_hint}"
  242     );
  243 }
