  245 fn print_detach_json(transfer_id: &str) {
  246     println!(
  247         "{}",
  248         serde_json::to_string_pretty(&serde_json::json!({
  249             "outcome": "detached",
  250             "transfer_id": transfer_id,
  251         }))
  252         .unwrap_or_default()
  253     );
  254 }
