  256 fn print_delegated_json(
  257     summary: &DelegatedPullSummary,
  258     src: &RemoteEndpoint,
  259     dst: &RemoteEndpoint,
  260 ) {
  261     use serde_json::json;
  262     // pfc-5: same two fields, same shape, as every other route's document.
  263     let failures = super::failures::failures_from_wire(&summary.failures);
  264     let body = json!({
  265         "operation": "delegated_pull",
  266         "source": format_remote_endpoint(src),
  267         "destination": format_remote_endpoint(dst),
  268         "files_transferred": summary.files_transferred,
  269         "bytes_transferred": summary.bytes_transferred,
  270         "bytes_zero_copy": summary.bytes_zero_copy,
  271         "entries_deleted": summary.entries_deleted,
  272         "tcp_fallback": summary.tcp_fallback_used,
  273         "source_peer_observed": summary.source_peer_observed,
  274         "files_failed": summary.files_failed,
  275         "failures": super::failures::failures_json(&failures),
  276     });
  277     println!("{}", serde_json::to_string_pretty(&body).unwrap());
  278 }
